import { useState } from 'react';
import { Send } from 'lucide-react';
import VoiceButton from './VoiceButton';

export default function ChatInput({
  onSend,
  onVoiceStart,
  disabled = false,
  voiceSupported = false,
  listening = false,
  voiceError = null,
  placeholder = 'Type your answer…',
}) {
  const [value, setValue] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();

    const trimmed = value.trim();

    if (!trimmed || disabled) return;

    onSend(trimmed);
    setValue('');
  };

  const handleVoiceClick = () => {
    if (disabled || !voiceSupported) return;
    onVoiceStart?.();
  };

  return (
    <div>
      {voiceError && (
        <div className="rl-voice-error" role="alert">
          {voiceError}
        </div>
      )}

      <form className="rl-input-bar" onSubmit={handleSubmit}>
        <VoiceButton
          disabled={disabled || !voiceSupported}
          listening={listening}
          onClick={handleVoiceClick}
        />

        <input
          type="text"
          className="rl-input-bar__field"
          value={value}
          onChange={(e) => setValue(e.target.value)}
          placeholder={
            listening
              ? 'Listening…'
              : placeholder
          }
          disabled={disabled}
          aria-label="Type your answer"
        />

        <button
          type="submit"
          className="rl-input-bar__send"
          disabled={disabled || !value.trim()}
          aria-label="Send message"
        >
          <Send size={16} strokeWidth={2.3} />
        </button>
      </form>
    </div>
  );
}
